<?php
require_once __DIR__ . '/auth.php'; require_login();
$pdo=db(); $id=(int)($_GET['id']??$_POST['id']??0); $err='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    try{ $_POST = normalize_customer_input($_POST); $errors = validate_customer_input($_POST); if ($errors) { throw new Exception(implode('<br>', $errors)); } $st=$pdo->prepare('UPDATE customers SET company_name=?,postal_code=?,address=?,tel=?,fax=?,email=?,contact_name=? WHERE id=?'); $st->execute([trim($_POST['company_name']),trim($_POST['postal_code']??''),trim($_POST['address']??''),trim($_POST['tel']??''),trim($_POST['fax']??''),trim($_POST['email']??''),trim($_POST['contact_name']??''),$id]); header('Location: customer_list.php'); exit; }catch(Exception $e){$err=$e->getMessage();}
}
$st=$pdo->prepare('SELECT * FROM customers WHERE id=?'); $st->execute([$id]); $c=$st->fetch(); if(!$c){ echo 'データがありません'; exit; }
?>
<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>請求先編集</title><link rel="stylesheet" href="<?=asset_url('style.css')?>"></head><body><?php include 'header.php'; ?><div class="container"><h1>請求先編集</h1><?php if($err): ?><div class="msg err"><?=h($err)?></div><?php endif; ?><div class="card"><form method="post"><input type="hidden" name="id" value="<?=$id?>"><div class="grid2"><div><label>会社名</label><input name="company_name" value="<?=h($c['company_name'])?>" required></div><div><label>郵便番号</label><input name="postal_code" value="<?=h($c['postal_code'])?>" inputmode="numeric" pattern="[0-9]{3}-?[0-9]{4}" placeholder="123-4567" title="123-4567 の形式で入力してください"></div><div><label>住所</label><input name="address" value="<?=h($c['address'])?>"></div><div><label>電話番号</label><input name="tel" value="<?=h($c['tel'])?>" inputmode="numeric" pattern="[0-9\-]+" title="半角数字とハイフンで入力してください"></div><div><label>FAX</label><input name="fax" value="<?=h($c['fax'])?>" inputmode="numeric" pattern="[0-9\-]+" title="半角数字とハイフンで入力してください"></div><div><label>メール</label><input name="email" value="<?=h($c['email'])?>" type="email" inputmode="email" pattern="[A-Za-z0-9._%+\-@]+" title="半角英数字のメール形式で入力してください"></div><div><label>担当者</label><input name="contact_name" value="<?=h($c['contact_name'])?>"></div></div><div class="btns"><button class="btn green">更新</button><a class="btn gray" href="customer_list.php">戻る</a></div></form></div></div><script src="<?=asset_url('app.js')?>"></script></body></html>
